    /**
     * Method to retrieve the DeviceCertificate via DeviceCertificateFetchOneSummary
     * @param 	summary DeviceCertificateFetchOneSummary 
     * @return 	DeviceCertificateFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public DeviceCertificate getDeviceCertificate( DeviceCertificateFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "DeviceCertificateFetchOneSummary arg cannot be null" );
    	
    	DeviceCertificate entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a DeviceCertificate
        	// --------------------------------------
        	CompletableFuture<DeviceCertificate> futureEntity = queryGateway.query(new FindDeviceCertificateQuery( new LoadDeviceCertificateFilter( summary.getDeviceCertificateId() ) ), ResponseTypes.instanceOf(DeviceCertificate.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate DeviceCertificate with id " + summary.getDeviceCertificateId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


